-              meaning. */
-            line = line.substring(2);
-            if ("[K".equals(line)) {
-                inProgressReport = true;
-            }
-            return null;
-        }
-        if (line.startsWith(squashedPrefix)) {
-            line = line.substring(squashedPrefix.length());
-            inProgressReport = false;
-            lastLine = line;
